        var summary=CardPanel();summary.Controls.Add(Label("CURRENT ANALYSIS SUMMARY",new Point(18,15),new Size(500,28),new Font("Segoe UI Semibold",13,FontStyle.Bold),Cyan));var active=InnerCard(new Point(18,55),new Size(410,155));active.Controls.Add(Label("⌁  ACTIVE GAME",new Point(18,14),new Size(260,26),new Font("Segoe UI Semibold",11,FontStyle.Bold),Cyan));gameName.Text="No game detected";gameName.Location=new Point(20,50);gameName.Size=new Size(360,30);gameName.Font=new Font("Segoe UI Semibold",15,FontStyle.Bold);active.Controls.Add(gameName);gameMeta.Text="Start an online game and click AUTO ANALYZE";gameMeta.Location=new Point(20,84);gameMeta.Size=new Size(370,60);gameMeta.ForeColor=Muted;active.Controls.Add(gameMeta);summary.Controls.Add(active);var conn=InnerCard(new Point(445,55),new Size(430,155));conn.Controls.Add(Label("⚙  CONNECTIONS DISCOVERED",new Point(18,14),new Size(360,26),new Font("Segoe UI Semibold",11,FontStyle.Bold),Cyan));conn.Controls.Add(Label("Automatically discovers public endpoints from the active game process.\nNo IP copying is required.",new Point(18,52),new Size(380,80),new Font("Segoe UI",10),Muted));summary.Controls.Add(conn);wrap.Controls.Add(summary,0,1);
